```{.r .cell-code  code-fold="true" code-summary="The `get_table_mc()`{.R} and `get_formatted_table()`{.R} functions used to produce the Tables and the definition of the configurations for a set of $n$, $p$ and $R_d^2$."}
get_col_table <- function(estimator, 
                          calib, 
                          lab,
                          n_val = 2000,
                          p_val = 200,
                          rd2_val = 0.8) {
  res_ate |>
    filter(
      n == n_val,
      p == p_val,
      Rd2 == rd2_val,
      calib_name == !!calib
    ) |> 
    mutate(
      estim_ate = !!sym(estimator)
    ) |>
    group_by(g_name, m_name) |> 
    summarise(
      bias = mean(estim_ate - ate_true),
      sd   = sd(estim_ate - ate_true),
      .groups = "drop"
    ) |> 
    pivot_longer(
      cols = c(bias, sd),
      names_to = "metric",
      values_to = "value"
    ) |> 
    mutate(
      column = !!lab
    ) |> 
    unite(
      col = "column",
      column,
      metric,
      sep = "__"
    ) |> 
    pivot_wider(
      names_from = column,
      values_from = value
    )
}

get_formatted_table <- function(configs, 
                                n_val, 
                                p_val, 
                                rd2_val) {
  table_data <- 
    pmap(configs, function(estimator, calib, lab) {
      get_col_table(
        estimator = estimator, calib = calib, lab = lab, 
        n_val = n_val, p_val = p_val, rd2_val = rd2_val)
    }) |> 
    reduce(left_join, by = c("g_name", "m_name")) |> 
    mutate(
      g_name = factor(
        g_name,
        levels = c("ols", "lasso", "rf", "lgbm"),
        labels = c("Outcome: OLS", "Outcome: Lasso", "Outcome: Random Forest", "Outcome: Boosting")
      ),
      m_name = factor(
        m_name,
        levels = c("logit", "rf_classif", "rf_reg", "lgbm"),
        labels = c("Logit", "RF Classif", "RF Reg", "Boosting")
      )
    ) |> 
    arrange(g_name, m_name)

  formatted_table <- table_data |>
    gt(
      rowname_col = "m_name",
      groupname_col = "g_name"
    ) |>
    tab_spanner_delim(
      delim = "__",
      columns = contains("__")
    ) |>
    cols_label(
      .list = setNames(
        ifelse(
          endsWith(names(table_data), "__bias"),
          "Bias",
          ifelse(
            endsWith(names(table_data), "__sd"),
            "(SD)",
            names(table_data)
          )
        ),
        names(table_data)
      )
    ) |>
    fmt_number(
      columns = ends_with("__bias"),
      decimals = 3
    ) |>
    fmt_number(
      columns = ends_with("__sd"),
      decimals = 3,
      pattern = "({x})"
    ) |>
    cols_align(
      align = "center",
      columns = contains("__")
    ) |>
    tab_header(
      title = md("**Monte Carlo Simulation Results**"),
      subtitle = md(
        glue("*n* = {n_val}, *p* = {p_val}, Rd² = {rd2_val}")
      )
    ) |>
    opt_stylize(style = 1, color = "gray") |>
    tab_options(
      column_labels.font.weight = "bold",
      row_group.font.weight = "bold"
    )

  formatted_table
}

configs <- tribble(
  ~estimator, ~calib, ~lab,
  "ate_aipw",      "uncalibrated",       "Uncalibrated",
  "ate_aipw_norm", "uncalibrated",       "Hájek",
  "ate_aipw",      "uncalib-platt-clip", "Clipped",
  "ate_aipw",      "isotonic",           "Isotonic"
)
